INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3975837',2009,83,'P1','Contabilidade Geral - CPC 16 - Tratamento Contábil para os Estoques','FCC - AFRE GO/SEFAZ GO/2026','Caderno Contabilidade Geral Parte 1','Uma empresa adquiriu, à vista, um lote de mercadorias pelo valor de R$ 1.000.000. A compra foi realizada em 18/11/2024 e a empresa compradora responsabilizou-se pela retirada das mercadorias no depósito do fornecedor, pagando R$ 40.000 de frete para transportar essas mercadorias até seu depósito. A empresa pagou, adicionalmente, o valor de R$ 10.000 por um seguro contra roubo das mercadorias durante esse transporte. Nos diversos valores pagos estão incluídos impostos recuperáveis no valor de R$ 90.000 e impostos não recuperáveis no valor de R$ 70.000. Em 15/12/2024, a empresa vendeu 80% das mercadorias que havia comprado. O saldo evidenciado na conta Estoques, no Balanço Patrimonial de 31/12/2024, em relação exclusivamente a essas mercadorias, foi, em reais,','[["A","192.000"],["B","178.000"],["C","182.000"],["D","184.000"],["E","190.000"]]'::jsonb,'A',2026,127,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - CPC 16 - Tratamento Contábil para os Estoques.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é A."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"A — 192.000","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - CPC 16 - Tratamento Contábil para os Estoques"}'::jsonb,'Uma empresa adquiriu, à vista, um lote de mercadorias pelo valor de R$ 1.000.000. A compra foi realizada em 18/11/2024 e a empresa compradora responsabilizou-se pela retirada das mercadorias no depósito do fornecedor, pagando R$ 40.000 de frete para transportar essas mercadori...') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3994268',2010,83,'P1','Contabilidade Geral - CPC 16 - Tratamento Contábil para os Estoques','FGV - AFCE (TCE-SC)/TCE SC/Administração/2026','Caderno Contabilidade Geral Parte 1','Os estoques são mensurados inicialmente pelo custo de aquisição. Contudo, quando o valor de mercado torna-se inferior a esse custo, a contabilidade determina o reconhecimento da perda, de modo que o ativo não seja apresentado por valor superior ao efetivamente recuperável. Com base nesse critério, o procedimento a ser adotado, quando o valor de mercado do estoque for inferior a seu custo de aquisição, é','[["A","constituir provisão para perdas correspondente à diferença entre o custo e o valor de mercado, reduzindo o estoque ao seu montante recuperável."],["B","aguardar a efetiva alienação do estoque para, somente então, registrar a diferença entre o custo de aquisição e o valor obtido na venda."],["C","ajustar o valor contábil do estoque para cima sempre que o valor de mercado superar o custo registrado, reconhecendo o ganho no resultado."],["D","baixar integralmente o estoque a débito de despesa operacional no momento em que a queda do valor de mercado for constatada."],["E","manter o estoque pelo custo histórico enquanto não houver desembolso efetivo, pois perdas não realizadas financeiramente não afetam o resultado contábil."]]'::jsonb,'A',2026,128,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - CPC 16 - Tratamento Contábil para os Estoques.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é A."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"A — constituir provisão para perdas correspondente à diferença entre o custo e o valor de mercado, reduzindo o estoque ao seu montante recuperável.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - CPC 16 - Tratamento Contábil para os Estoques"}'::jsonb,'Os estoques são mensurados inicialmente pelo custo de aquisição. Contudo, quando o valor de mercado torna-se inferior a esse custo, a contabilidade determina o reconhecimento da perda, de modo que o ativo não seja apresentado por valor superior ao efetivamente recuperável. Com...') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4076217',2011,83,'P1','Contabilidade Geral - CPC 16 - Tratamento Contábil para os Estoques','FGV - Ana (TJ SC)/TJ SC/Contábil-Econômico/2026','Caderno Contabilidade Geral Parte 1','Em 31/12/2025, uma entidade apresentava os seguintes saldos em seu Balanço Patrimonial: disponibilidades de R$ 20.000; estoques de R$ 10.000 e capital social de R$ 30.000. O estoque era formado por 200 unidades do produto X, originalmente vendidas por R$ 80 cada. Em razão da necessidade de liberar espaço em seu depósito para a introdução de um novo produto a partir de fevereiro, a entidade reduziu o preço de venda do produto X para R$ 40 por unidade. Em janeiro de 2026, foram vendidas 170 unidades desse produto, à vista, pelo novo preço. Considerando as informações apresentadas, ao comparar o patrimônio líquido da entidade em janeiro de 2026 com o mês anterior, verifica-se que ele','[["A","diminuiu R$ 1.700."],["B","diminuiu R$ 2.000."],["C","diminuiu R$ 8.000."],["D","aumentou R$ 2.000."],["E","aumentou R$ 8.000."]]'::jsonb,'B',2026,129,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - CPC 16 - Tratamento Contábil para os Estoques.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é B."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"B — diminuiu R$ 2.000.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - CPC 16 - Tratamento Contábil para os Estoques"}'::jsonb,'Em 31/12/2025, uma entidade apresentava os seguintes saldos em seu Balanço Patrimonial: disponibilidades de R$ 20.000; estoques de R$ 10.000 e capital social de R$ 30.000. O estoque era formado por 200 unidades do produto X, originalmente vendidas por R$ 80 cada. Em razão da n...') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3907967',2012,83,'P1','Contabilidade Geral - CPC 16 - Tratamento Contábil para os Estoques','FADESP - ACAE (SEFA PA)/SEFA PA/2026','Caderno Contabilidade Geral Parte 1','Em 31/12/2024, a empresa AmazonTech ficou com um saldo na conta de estoque de equipamentos no valor de R$ 350.000,00 (caso hipotético). Em virtude de os equipamentos tecnológicos estarem sujeitos a desvalorização por inovação tecnológica, a empresa realizou uma avaliação do valor realizável líquido dos equipamentos e apurou um montante de R$ 200.000,00. Em janeiro de 2025, a empresa fez uma promoção e vendeu todos os equipamentos por R$ 300.000,00, tendo um gasto de R$ 2.000,00 com frete para entregar a mercadoria ao cliente e R$ 3.000,00 de comissão para os vendedores. Considerando somente essas informações, o resultado da operação, em 2025, é','[["A","R$ 100.000,00."],["B","(R$ 55.000,00)."],["C","(R$ 50.000,00)."],["D","R$ 95.000,00."],["E","(R$ 150.000,00)."]]'::jsonb,'D',2026,130,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - CPC 16 - Tratamento Contábil para os Estoques.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é D."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"D — R$ 95.000,00.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - CPC 16 - Tratamento Contábil para os Estoques"}'::jsonb,'Em 31/12/2024, a empresa AmazonTech ficou com um saldo na conta de estoque de equipamentos no valor de R$ 350.000,00 (caso hipotético). Em virtude de os equipamentos tecnológicos estarem sujeitos a desvalorização por inovação tecnológica, a empresa realizou uma avaliação do va...') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3914808',2013,83,'P1','Contabilidade Geral - CPC 16 - Tratamento Contábil para os Estoques','FEPESE - Per Of Crim (PCien SC)/PCien SC/Ciências Sociais Aplicadas/2026','Caderno Contabilidade Geral Parte 1','Caso 3 Para responder à questão, considere: A Companhia Paraíba produz apenas dois produtos: barra de chocolate e caixa de bombons, cujos preços de venda, líquidos de impostos, são de R$ 20 e R$ 25, respectivamente. Durante um período, o volume de produção foi de 2.000 unidades de cada produto e o volume de vendas foi de 1.500 unidades de cada produto. Sua estrutura de custos é a seguinte: Custos variáveis por unidade Barra de chocolate (R$) Caixa de bombons (R$) Matéria-prima 3 4 Material de embalagem 2 3 Mão de obra direta 5 7 Custos fixos no período Valores (R$) Supervisão da produção 5.000,00 Depreciação 3.000,00 Outros 2.000,00 A Companhia Paraíba aloca os custos fixos aos produtos pelo critério da proporcionalidade do tempo de mão de obra direta. São necessários 4 minutos para produzir uma barra de chocolate e 6 minutos para produzir uma caixa de bombom. O valor do custo unitário da barra de chocolate e da caixa de bombons pelo sistema de custeio por absorção foi, respectivamente, de:','[["A","R$ 11,00 e R$ 18,00."],["B","R$ 12,00 e R$ 17,00."],["C","R$ 12,17 e R$ 17,14."],["D","R$ 12,50 e R$ 17,25."],["E","R$ 12,67 e R$ 17,28."]]'::jsonb,'B',2026,131,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - CPC 16 - Tratamento Contábil para os Estoques.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é B."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"B — R$ 12,00 e R$ 17,00.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - CPC 16 - Tratamento Contábil para os Estoques"}'::jsonb,'Caso 3 Para responder à questão, considere: A Companhia Paraíba produz apenas dois produtos: barra de chocolate e caixa de bombons, cujos preços de venda, líquidos de impostos, são de R$ 20 e R$ 25, respectivamente. Durante um período, o volume de produção foi de 2.000 unidade...') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3992085',2014,83,'P1','Contabilidade Geral - CPC 16 - Tratamento Contábil para os Estoques','FGV - Bach (CFC)/CFC/1º Exame de Suficiência/2026','Caderno Contabilidade Geral Parte 1','Uma empresa varejista adquiriu mercadoria à vista para revenda no curto prazo. Os dados relacionados a essa compra são: Valor unitário: R$ 200,00; Quantidade adquirida: 1.000 unidades; Imposto de importação: R$ 10,00/unidade (por fora do preço de aquisição); Seguro: R$ 6.000,00; Transporte da mercadoria: R$ 4.000,00; Imposto de circulação de mercadorias (ICMS): R$ 20,00/unidade (embutido no preço de aquisição); Desconto comercial: R$ 15,00/unidade. Considerando o ICMS como um tributo não recuperável pela empresa adquirente, e com base exclusivamente nos dados apresentados, o custo total do estoque adquirido é de','[["A","R$ 205.000,00."],["B","R$ 210.000,00."],["C","R$ 220.000,00."],["D","R$ 235.000,00."]]'::jsonb,'A',2026,132,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - CPC 16 - Tratamento Contábil para os Estoques.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é A."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"A — R$ 205.000,00.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - CPC 16 - Tratamento Contábil para os Estoques"}'::jsonb,'Uma empresa varejista adquiriu mercadoria à vista para revenda no curto prazo. Os dados relacionados a essa compra são: Valor unitário: R$ 200,00; Quantidade adquirida: 1.000 unidades; Imposto de importação: R$ 10,00/unidade (por fora do preço de aquisição); Seguro: R$ 6.000,0...') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3975808',2015,69,'P2','Contabilidade Geral - Operações com Mercadorias (CMV, RCM, Tributos, Frete, etc.)','FCC - AFRE GO/SEFAZ GO/2026','Caderno Contabilidade Geral Parte 1','No dia 23/10/2023, a empresa Comprando e Vendendo S.A. adquiriu mercadorias para revenda e pagou os seguintes valores: R$ 1.010.250 para o fornecedor das mercadorias. R$ 30.000 para a transportadora que levou as mercadorias até sua loja. Estão incluídos nesses valores pagos, os seguintes tributos: Tributos recuperáveis no valor total de R$ 138.000 Tributos não recuperáveis no valor total de R$ 96.000 Em 10/12/2023, a empresa vendeu 80% das mercadorias pelo valor R$ 2.700.000, mas concedeu um desconto comercial de 10% em função da quantidade adquirida pelo comprador. Os impostos sobre a venda são de 10% sobre o valor líquido da venda, a empresa pagou para seus vendedores o valor de R$ 48.600 a título de comissão e R$ 42.000 para a transportadora que fez a entrega das mercadorias vendidas. O lucro bruto apurado pela empresa Comprando e Vendendo S.A., especificamente em relação à compra e venda das mercadorias citadas, foi, em reais,','[["A","1.374.600"],["B","1.708.200"],["C","1.542.000"],["D","1.416.600"],["E","1.465.200"]]'::jsonb,'E',2026,140,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Operações com Mercadorias (CMV, RCM, Tributos, Frete, etc.).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é E."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"E — 1.465.200","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Operações com Mercadorias (CMV, RCM, Tributos, Frete, etc.)"}'::jsonb,'No dia 23/10/2023, a empresa Comprando e Vendendo S.A. adquiriu mercadorias para revenda e pagou os seguintes valores: R$ 1.010.250 para o fornecedor das mercadorias. R$ 30.000 para a transportadora que levou as mercadorias até sua loja. Estão incluídos nesses valores pagos, o...') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4014364',2016,69,'P2','Contabilidade Geral - Operações com Mercadorias (CMV, RCM, Tributos, Frete, etc.)','Instituto AOCP - Tec (IF CE)/IF CE/Contabilidade/2026','Caderno Contabilidade Geral Parte 1','A margem de contribuição de um produto representa a diferença entre o preço de venda e','[["A","os custos fixos do produto."],["B","os custos variáveis do produto."],["C","todos os custos e as despesas da empresa."],["D","os impostos sobre vendas."],["E","o lucro líquido obtido."]]'::jsonb,'B',2026,141,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Operações com Mercadorias (CMV, RCM, Tributos, Frete, etc.).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é B."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"B — os custos variáveis do produto.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Operações com Mercadorias (CMV, RCM, Tributos, Frete, etc.)"}'::jsonb,'A margem de contribuição de um produto representa a diferença entre o preço de venda e') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, r