 com Mercadorias (CMV, RCM, Tributos, Frete, etc.)"}'::jsonb,'Determinada empresa iniciou o exercício social com um estoque de mercadorias no valor de R$ 1.920.000 e, ao longo do período, adquiriu mercadorias à vista por R$ 4.800.000 e a prazo por R$ 1.600.000. No mesmo exercício, a sociedade realizou vendas de mercadorias à vista no val...') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
